src/MissionTreasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title MissionTreasury
 * @notice Master treasury for kids support reserves across all platform DAOs.
 *
 *         Receives 10% from each PlatformSplitter10 bucket.
 *         Holds funds until verified disbursement event.
 *         After founder death (confirmed by DeadManSwitch + Gnosis Safe 3-of-5),
 *         ownership transfers to mission governance — Founding Four + DAO token holders.
 *
 *         MISSION SCOPE (per founder directive §12.6, 2026-04-19):
 *         NOT limited to medical needs. Covers ALL child welfare categories:
 *         medical/health, hunger/food security, education/school supplies,
 *         children in war zones, foster care, housing/shelter, mental health,
 *         and any other unmet child need. If a kid needs it, it's in scope.
 *
 *         State A (alive):  Josh controls disbursements
 *         State B (dead):   Gnosis Safe 3-of-5 controls disbursements
 *
 *         No human board. No 501(c)(3). No nonprofit. Perpetual mission DAO.
 *
 *         "Until no kid is in need" — Joshua Coleman
 */
contract MissionTreasury is Ownable {
    using SafeERC20 for IERC20;

    address public constant USDC = 0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913;

    address public immutable deadManSwitch;
    address public immutable gnosisSafe; // Takes ownership on State B

    bool public stateBActive;

    // Per-bucket accounting
    mapping(string => uint256) public bucketReceived;
    mapping(string => uint256) public bucketDisbursed;

    // Approved disbursement targets (kids orgs, direct recipients)
    mapping(address => string) public approvedRecipients; // address → name
    mapping(address => bool) public isApproved;

    struct Disbursement {
        address recipient;
        uint256 amount;
        string bucketId;
        string purpose;
        uint256 timestamp;
    }
    Disbursement[] public disbursements;

    event FundsReceived(address indexed from, uint256 amount, string bucketId);
    event Disbursed(address indexed recipient, uint256 amount, string bucketId, string purpose);
    event RecipientApproved(address indexed recipient, string name);
    event RecipientRevoked(address indexed recipient);
    event StateBActivated(bytes32 certificateHash, uint256 timestamp);

    error OnlyDeadManSwitch();
    error AlreadyStateB();
    error NotApproved();
    error InsufficientFunds();
    error ZeroAddress();
    error ZeroAmount();

    modifier onlyDeadManSwitch() {
        if (msg.sender != deadManSwitch) revert OnlyDeadManSwitch();
        _;
    }

    constructor(address _deadManSwitch, address _gnosisSafe, address _founder)
        Ownable(_founder)
    {
        if (_deadManSwitch == address(0)) revert ZeroAddress();
        if (_gnosisSafe == address(0)) revert ZeroAddress();
        deadManSwitch = _deadManSwitch;
        gnosisSafe = _gnosisSafe;
    }

    // Accept USDC deposits from PlatformSplitter10 contracts
    // Call after transferring USDC to record which bucket it came from
    function recordDeposit(uint256 amount, string calldata bucketId) external {
        bucketReceived[bucketId] += amount;
        emit FundsReceived(msg.sender, amount, bucketId);
    }

    // Disburse to approved recipient (Josh in State A, Gnosis Safe in State B)
    function disburse(
        address recipient,
        uint256 amount,
        string calldata bucketId,
        string calldata purpose
    ) external onlyOwner {
        if (!isApproved[recipient]) revert NotApproved();
        if (amount == 0) revert ZeroAmount();

        uint256 balance = IERC20(USDC).balanceOf(address(this));
        if (amount > balance) revert InsufficientFunds();

        IERC20(USDC).safeTransfer(recipient, amount);
        bucketDisbursed[bucketId] += amount;

        disbursements.push(Disbursement({
            recipient: recipient,
            amount: amount,
            bucketId: bucketId,
            purpose: purpose,
            timestamp: block.timestamp
        }));

        emit Disbursed(recipient, amount, bucketId, purpose);
    }

    // Called by DeadManSwitch when Gnosis Safe 3-of-5 confirms founder death
    // Ownership transfers to Gnosis Safe — irreversible
    function activateStateB(bytes32 certificateHash) external onlyDeadManSwitch {
        if (stateBActive) revert AlreadyStateB();
        stateBActive = true;
        _transferOwnership(gnosisSafe);
        emit StateBActivated(certificateHash, block.timestamp);
    }

    function approveRecipient(address recipient, string calldata name) external onlyOwner {
        if (recipient == address(0)) revert ZeroAddress();
        isApproved[recipient] = true;
        approvedRecipients[recipient] = name;
        emit RecipientApproved(recipient, name);
    }

    function revokeRecipient(address recipient) external onlyOwner {
        isApproved[recipient] = false;
        emit RecipientRevoked(recipient);
    }

    // Read-only stats
    function totalBalance() external view returns (uint256) {
        return IERC20(USDC).balanceOf(address(this));
    }

    function disbursementCount() external view returns (uint256) {
        return disbursements.length;
    }

    function getDisbursement(uint256 index) external view returns (Disbursement memory) {
        return disbursements[index];
    }
}

src/PlatformSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title PlatformSplitter
 * @notice Immutable 10/27/63 three-way revenue splitter for the ANTIGRAVITY multi-DAO
 *         ecosystem on Base L2. Pull-over-Push pattern — recipients withdraw their share.
 *
 *         10% → MissionReserve  (contractual revenue disbursement — youth initiatives)
 *         27% → TaxWallet       (covers 30% tax on the 90% operating share)
 *         63% → DAOTreasury     (operations, sinking fund, then staking surplus)
 *
 *         Deployed once per DAO. No owner. No admin. No upgrades.
 *         The split ratios are in the bytecode — no human can change them.
 *
 *         "Until no kid is in need" — Joshua Coleman, Founder
 */
contract PlatformSplitter {
    using SafeERC20 for IERC20;

    // --- Immutable addresses (set at deploy, never change) ---
    address public immutable missionReserve;
    address public immutable taxWallet;
    address public immutable daoTreasury;

    // USDC on Base Mainnet
    address public constant USDC = 0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913;

    // Split ratios in basis points — immutable in bytecode
    uint256 public constant MISSION_BPS  = 1000;  // 10%
    uint256 public constant TAX_BPS      = 2700;  // 27%
    uint256 public constant OPS_BPS      = 6300;  // 63%
    uint256 public constant TOTAL_BPS    = 10000;

    // --- Pull balances (packed into single slots where possible) ---
    uint128 public missionPending;
    uint128 public taxPending;
    uint128 public opsPending;
    uint128 private _padding; // storage packing alignment

    // --- Cumulative accounting ---
    uint256 public totalProcessed;

    // DAO identifier
    bytes32 public immutable daoId;

    // --- Events ---
    event Deposited(address indexed token, uint256 amount, bytes32 indexed daoId);
    event Withdrawn(address indexed recipient, address indexed token, uint256 amount);

    // --- Custom errors (cheaper than require strings) ---
    error ZeroAddress();
    error NothingToDeposit();
    error NothingToWithdraw();
    error Unauthorized();

    constructor(
        address _missionReserve,
        address _taxWallet,
        address _daoTreasury,
        bytes32 _daoId
    ) {
        if (_missionReserve == address(0)) revert ZeroAddress();
        if (_taxWallet == address(0)) revert ZeroAddress();
        if (_daoTreasury == address(0)) revert ZeroAddress();

        missionReserve = _missionReserve;
        taxWallet = _taxWallet;
        daoTreasury = _daoTreasury;
        daoId = _daoId;
    }

    /// @notice Deposit and split any USDC sitting in this contract.
    function deposit() external {
        uint256 balance = IERC20(USDC).balanceOf(address(this));
        if (balance == 0) revert NothingToDeposit();
        _deposit(balance);
    }

    /// @notice Deposit and split a specific ERC20 token.
    function depositToken(address token) external {
        uint256 balance = IERC20(token).balanceOf(address(this));
        if (balance == 0) revert NothingToDeposit();
        _depositToken(token, balance);
    }

    /// @notice Mission reserve withdraws its accumulated share.
    function withdrawMission() external {
        if (msg.sender != missionReserve) revert Unauthorized();
        uint128 amount = missionPending;
        if (amount == 0) revert NothingToWithdraw();
        missionPending = 0;
        IERC20(USDC).safeTransfer(missionReserve, amount);
        emit Withdrawn(missionReserve, USDC, amount);
    }

    /// @notice Tax wallet withdraws its accumulated share.
    function withdrawTax() external {
        if (msg.sender != taxWallet) revert Unauthorized();
        uint128 amount = taxPending;
        if (amount == 0) revert NothingToWithdraw();
        taxPending = 0;
        IERC20(USDC).safeTransfer(taxWallet, amount);
        emit Withdrawn(taxWallet, USDC, amount);
    }

    /// @notice DAO treasury withdraws its accumulated share.
    function withdrawOps() external {
        if (msg.sender != daoTreasury) revert Unauthorized();
        uint128 amount = opsPending;
        if (amount == 0) revert NothingToWithdraw();
        opsPending = 0;
        IERC20(USDC).safeTransfer(daoTreasury, amount);
        emit Withdrawn(daoTreasury, USDC, amount);
    }

    /// @notice Preview the three-way split for a given amount.
    function previewSplit(uint256 amount) external pure returns (
        uint256 mission,
        uint256 tax,
        uint256 ops
    ) {
        mission = (amount * MISSION_BPS) / TOTAL_BPS;
        tax = (amount * TAX_BPS) / TOTAL_BPS;
        ops = amount - mission - tax; // remainder avoids rounding loss
    }

    function pendingUSDC() external view returns (uint256) {
        return IERC20(USDC).balanceOf(address(this));
    }

    // --- Internal ---

    function _deposit(uint256 total) internal {
        uint128 missionAmt = uint128((total * MISSION_BPS) / TOTAL_BPS);
        uint128 taxAmt     = uint128((total * TAX_BPS) / TOTAL_BPS);
        uint128 opsAmt     = uint128(total - missionAmt - taxAmt);

        // Accumulate pull balances — single SSTORE per slot
        missionPending += missionAmt;
        taxPending     += taxAmt;
        opsPending     += opsAmt;

        totalProcessed += total;

        emit Deposited(USDC, total, daoId);
    }

    function _depositToken(address token, uint256 total) internal {
        uint256 missionAmt = (total * MISSION_BPS) / TOTAL_BPS;
        uint256 taxAmt     = (total * TAX_BPS) / TOTAL_BPS;
        uint256 opsAmt     = total - missionAmt - taxAmt;

        // For non-USDC tokens: push immediately (no pull accounting)
        IERC20(token).safeTransfer(missionReserve, missionAmt);
        IERC20(token).safeTransfer(taxWallet, taxAmt);
        IERC20(token).safeTransfer(daoTreasury, opsAmt);

        totalProcessed += total;

        emit Deposited(token, total, daoId);
    }
}

